seq = open("region.fasta").read().split("\n",1)[1].replace("\n","").strip()
print(len(seq))

def revcomp(s):
    return s.translate(str.maketrans("ACGT","TGCA"))[::-1]

stops = {"TAA","TGA","TAG"}
starts = {"ATG"}

def find_orfs(s):
    orfs = []
    for strand, ss in [("+",s),("-",revcomp(s))]:
        L = len(ss)
        for frame in range(3):
            i = frame
            while i < L-2:
                codon = ss[i:i+3]
                if codon in starts:
                    # scan forward
                    j = i
                    while j < L-2:
                        c = ss[j:j+3]
                        if c in stops:
                            orfs.append((strand, frame+1, i+1, j+3, (j+3-i)//3, i, j+3))
                            break
                        j += 3
                    else:
                        # runs off the end = partial ORF
                        orfs.append((strand, frame+1, i+1, L, (L-i)//3, i, L))
                    i = j+1 if j > i else i+3
                else:
                    i += 3
    return orfs

orfs = find_orfs(seq)
print("total ORF-like segments:", len(orfs))
# longest complete ORFs per strand
for strand in "+-":
    lst = sorted([o for o in orfs if o[0]==strand], key=lambda x:-x[4])[:8]
    print("strand", strand)
    for o in lst:
        print("  frame %d  nt %d-%d  len %d aa" % (o[1], o[2], o[3], o[4]))
