def revcomp(s):
    return s.translate(str.maketrans("ACGT","TGCA"))[::-1]

stops = {"TAA","TGA","TAG"}

def frame_of(idx):
    return (idx % 3) + 1

def scan(s, offsets):
    f1,f2,f3 = offsets
    res = []
    for frame,delta in [(1,f1),(2,f2),(3,f3)]:
        # build list of start positions in this frame
        i = delta
        while i < len(s)-2:
            if s[i:i+3] == "ATG":
                # scan to stop OR end
                j = i
                end = None
                while j < len(s)-2:
                    if s[j:j+3] in stops:
                        end = j+3
                        break
                    j += 3
                if end is None:
                    end = len(s)  # runs off end
                    if (end - i)//3 >= 30:
                        res.append((frame, i+1, end, (end-i)//3, "3'partial"))
                else:
                    res.append((frame, i+1, end, (end-i)//3, "complete"))
                i += 1
            else:
                i += 1
    return res

raw_plus = scan(seq, (0,1,2))
rc = revcomp(seq)
raw_minus = scan(rc, (0,1,2))

print("=== + strand, complete ORFs >=30 nt (frame, start, end, aa) ===")
for r in sorted([x for x in raw_plus if x[4]=="complete" and x[3]>=15], key=lambda x:-x[3])[:10]:
    print(r)
print("=== - strand, complete ORFs (coords on rc; convert below) ===")
for r in sorted([x for x in raw_minus if x[4]=="complete" and x[3]>=15], key=lambda x:-x[3])[:10]:
